const std=@import("std");const S=@import("experimental/scalar_water.zig");
test "actual recharge crosses binades exactly"{for([_]f64{0.0001666666666666483,0.00008333333333332415,0.00004166666666666208})|target|{const r=S.transfer(705.3308409072768,target,0.25);try std.testing.expect(r.accepted);try std.testing.expectEqual(@as(f64,0.25),r.paid);try std.testing.expectEqual(@as(f128,r.paid),@as(f128,@as(f64,705.3308409072768))-r.source);try std.testing.expectEqual(@as(f128,r.paid),@as(f128,r.target)-target);}}
test "zero invalid extreme and unrepresentable remain atomic"{const z=S.transfer(1,0,0);try std.testing.expect(z.accepted and z.paid==0);for([_]struct{s:f64,t:f64,w:f64}{.{.s=1,.t=1e100,.w=1},.{.s=1,.t=std.math.floatMax(f64),.w=1},.{.s=-1,.t=0,.w=1},.{.s=1,.t=0,.w=std.math.inf(f64)}})|v|{const r=S.transfer(v.s,v.t,v.w);try std.testing.expect(!r.accepted);try std.testing.expectEqual(v.s,r.source);try std.testing.expectEqual(v.t,r.target);}}
test "scalar fixed broad exact probes"{var rng=std.Random.DefaultPrng.init(72);for(0..5000)|i|{const e=rng.random().intRangeAtMost(i32,-120,120);const s=std.math.pow(f64,2,@floatFromInt(e))*(1+rng.random().float(f64));const t=std.math.pow(f64,2,@floatFromInt(rng.random().intRangeAtMost(i32,-120,120)))*rng.random().float(f64);const w=s*rng.random().float(f64);const r=S.transfer(s,t,w);if(r.accepted){try std.testing.expect(r.paid<=w);try std.testing.expectEqual(@as(f128,s)-r.source,@as(f128,r.target)-t);}std.debug.print("SCALAR {d} {d} {d} {d} {d} {d} {d} {}\n",.{i,s,t,w,r.source,r.target,r.paid,r.accepted});}}
